const p = $json.product;
const sellingPrice = Number(p.selling_price) || 0;
const supplierPrice = Number(p.supplier_price) || 0;
const grossProfit = sellingPrice - supplierPrice;
const marginPercent = sellingPrice > 0 ? (grossProfit / sellingPrice) * 100 : 0;

return {
  json: Object.assign({}, p, {
    gross_profit: Number(grossProfit.toFixed(2)),
    margin_percent: Number(marginPercent.toFixed(2)),
    demand_score: 5,
    competition_score: 5,
    creative_potential_score: 5,
    impulse_purchase_score: 5,
    problem_solution_score: 5,
    trust_risk_score: 5,
    score_source: "demo"
  })
};

const original = $('05 - Prepare Saudi Analysis').item.json;
const httpResponse = $json;

let aiText = '';
try {
  aiText = (httpResponse.choices && httpResponse.choices[0] && httpResponse.choices[0].message && httpResponse.choices[0].message.content) || '';
} catch (e) {
  aiText = '';
}

let cleaned = (aiText || '').trim();
if (cleaned.indexOf('```') === 0) {
  cleaned = cleaned.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}

let parsed = null;
let ai_parse_error = false;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  ai_parse_error = true;
  parsed = {
    target_customer: "",
    main_problem: "",
    selling_angle: "",
    saudi_market_fit_score: 0,
    creative_potential_score: 0,
    impulse_purchase_score: 0,
    competition_risk_score: 0,
    trust_risk_score: 0,
    recommended_platform: "",
    reason: "AI response could not be parsed",
    hooks: []
  };
}

return {
  json: Object.assign({}, original, parsed, { ai_parse_error: ai_parse_error })
};

const item = $json;

function clamp(n, min, max) {
  const num = Number(n) || 0;
  return Math.min(max, Math.max(min, num));
}

const saudiFit = clamp(item.saudi_market_fit_score, 0, 10);
const creative = clamp(item.creative_potential_score, 0, 10);
const impulse = clamp(item.impulse_purchase_score, 0, 10);
const problemSolution = clamp(item.problem_solution_score, 0, 10);
const competitionRisk = clamp(item.competition_risk_score !== undefined ? item.competition_risk_score : item.competition_score, 0, 10);
const trustRisk = clamp(item.trust_risk_score, 0, 10);

const marginPercent = Number(item.margin_percent) || 0;
const normalizedMarginScore = clamp(marginPercent / 8, 0, 10);

const weights = {
  saudiFit: 0.25,
  margin: 0.20,
  creative: 0.20,
  impulse: 0.15,
  problemSolution: 0.10,
  competition: 0.05,
  trust: 0.05
};

const positiveContribution =
  (weights.saudiFit * saudiFit) +
  (weights.margin * normalizedMarginScore) +
  (weights.creative * creative) +
  (weights.impulse * impulse) +
  (weights.problemSolution * problemSolution);

const negativeContribution =
  (weights.competition * (10 - competitionRisk)) +
  (weights.trust * (10 - trustRisk));

const rawScore = (positiveContribution + negativeContribution) * 10;
const finalScore = clamp(rawScore, 0, 100);

let recommendation = 'REJECT';
if (finalScore >= 85) {
  recommendation = 'STRONG TEST';
} else if (finalScore >= 70) {
  recommendation = 'TEST';
} else if (finalScore >= 55) {
  recommendation = 'WATCH';
}

return {
  json: Object.assign({}, item, {
    final_score: Number(finalScore.toFixed(2)),
    score_breakdown: {
      saudi_market_fit: saudiFit,
      margin_normalized: Number(normalizedMarginScore.toFixed(2)),
      creative_potential: creative,
      impulse_purchase: impulse,
      problem_solution: problemSolution,
      competition_risk: competitionRisk,
      trust_risk: trustRisk,
      weights: weights
    },
    recommendation: recommendation
  })
};

const config = $('00 - Config').first().json;
const topN = Number(config.top_n) || 3;

const allItems = $input.all().map(function(i) { return i.json; });

const top = allItems.slice(0, topN).map(function(item, index) {
  return {
    rank: index + 1,
    product_name: item.product_name,
    category: item.category,
    selling_price: item.selling_price,
    gross_profit: item.gross_profit,
    margin_percent: item.margin_percent,
    final_score: item.final_score,
    recommendation: item.recommendation,
    recommended_platform: item.recommended_platform,
    selling_angle: item.selling_angle,
    main_problem: item.main_problem,
    hooks: item.hooks,
    product_url: item.product_url
  };
});

return top.map(function(item) { return { json: item }; });
